  --radius-xl: 24px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--dark);
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }

a {
  color: var(--primary);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover { color: var(--primary-dark); }

img { max-width: 100%; height: auto; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-dark);
  color: var(--white);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: var(--white);
  color: var(--primary);
  border: 2px solid var(--primary);
}

.btn-secondary:hover {
  background: var(--gray-50);
  color: var(--primary-dark);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
}

.btn-accent:hover {
  background: #c44445;
  color: var(--white);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--dark);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg { width: 22px; height: 22px; }

.nav-desktop {
  display: none;
  align-items: center;
  gap: 32px;
}

.nav-desktop a {
  font-weight: 500;
  color: var(--gray-700);
}

.nav-desktop a:hover { color: var(--primary); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

/* Mobile Nav */
.mobile-nav-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}

.mobile-nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--dark);
  border-radius: 2px;
  transition: all 0.3s;
}

.mobile-nav {
  position: fixed;
  top: 0;
  right: -100%;
  width: 280px;
  height: 100vh;
  background: var(--white);
  box-shadow: var(--shadow-xl);
  z-index: 200;
  transition: right 0.3s ease;
  padding: 24px;
}

.mobile-nav.open { right: 0; }

.mobile-nav-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 32px;
}

.mobile-nav-close {
  background: none;
  border: none;
  font-size: 28px;
  cursor: pointer;
  color: var(--gray-600);
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.mobile-nav-links a {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--gray-800);
}

.mobile-nav-links a:hover { color: var(--primary); }

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 150;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s;
}

.mobile-overlay.open {
  opacity: 1;
  visibility: visible;
}

/* Hero */
.hero {
  padding: 80px 0 60px;
  text-align: center;
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
}

.hero h1 {
  max-width: 800px;
  margin: 0 auto 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto 40px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 16px;
}

/* Page Hero (inner pages) */
.page-hero {
  padding: 60px 0 50px;
  text-align: center;
  background: var(--gray-50);
}

.page-hero h1 { margin-bottom: 16px; }

.page-hero p {
  font-size: 1.125rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto;
}

/* Sections */
.section {
  padding: 80px 0;
}

.section-alt { background: var(--gray-50); }

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 48px;
}

.section-header h2 { margin-bottom: 16px; }

.section-header p {
  font-size: 1.125rem;
  color: var(--gray-600);
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
}

.feature-card {
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  transition: all 0.2s;
}

.feature-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.feature-icon {
  width: 56px;
  height: 56px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 24px;
}

.feature-card h3 { margin-bottom: 12px; }

.feature-card p { color: var(--gray-600); }

/* How It Works */
.how-it-works-steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 40px;
}

.step {
  text-align: center;
  position: relative;
}

.step-number {
  width: 48px;
  height: 48px;
  background: var(--primary);
  color: var(--white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0 auto 20px;
}

.step h3 { margin-bottom: 12px; }

.step p { color: var(--gray-600); }

/* Testimonials */
.testimonials-wrapper {
  position: relative;
  overflow: hidden;
  padding: 20px 0;
}

.testimonials-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 40px;
  background: var(--white);
  border-radius: var(--radius-lg);
  text-align: center;
  border: 1px solid var(--gray-200);
}

.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--gray-700);
  margin-bottom: 24px;
  line-height: 1.8;
}

.testimonial-author {
  font-weight: 600;
  color: var(--dark);
}

.testimonial-role {
  color: var(--gray-600);
  font-size: 0.875rem;
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.testimonial-nav button {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--gray-200);
  background: var(--white);
  cursor: pointer;
  font-size: 20px;
  color: var(--gray-600);
  transition: all 0.2s;
}

.testimonial-nav button:hover {
  border-color: var(--primary);
  color: var(--primary);
}

/* Stats Banner */
.stats-banner {
  background: var(--dark);
  padding: 60px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.stat-item {
  text-align: center;
}

.stat-number {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 800;
  color: var(--white);
  margin-bottom: 8px;
}

.stat-label {
  color: var(--gray-400);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* Pricing Toggle */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

.toggle-label {
  font-weight: 600;
  color: var(--gray-600);
}

.toggle-label.active { color: var(--dark); }

.toggle-switch {
  width: 56px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 14px;
  position: relative;
  cursor: pointer;
  transition: background 0.2s;
}

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  top: 3px;
  left: 3px;
  transition: transform 0.2s;
}

.toggle-switch.annual::after { transform: translateX(28px); }

.save-badge {
  background: var(--success);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}

/* Pricing Cards */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.pricing-card {
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  text-align: center;
  transition: all 0.2s;
}

.pricing-card.featured {
  border-color: var(--primary);
  position: relative;
  transform: scale(1.02);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: 20px;
}

.pricing-card h3 {
  font-size: 1.5rem;
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
  margin-bottom: 8px;
}

.pricing-card .price-period {
  color: var(--gray-500);
  font-weight: 400;
}

.pricing-card .description {
  color: var(--gray-600);
  margin-bottom: 24px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--gray-200);
}

.pricing-features {
  list-style: none;
  text-align: left;
  margin-bottom: 32px;
}

.pricing-features li {
  padding: 10px 0;
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--gray-700);
}

.pricing-features li .check {
  color: var(--success);
  font-weight: 700;
}

.pricing-features li .cross {
  color: var(--gray-400);
}

.pricing-features li .limited {
  color: var(--gray-500);
  font-size: 0.875rem;
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  color: var(--dark);
}

.faq-question:hover { color: var(--primary); }

.faq-icon {
  font-size: 1.5rem;
  color: var(--gray-400);
  transition: transform 0.3s;
}

.faq-item.open .faq-icon { transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 200px;
  padding-bottom: 24px;
}

.faq-answer p { color: var(--gray-600); }

/* CTA Section */
.cta-section {
  background: var(--primary);
  padding: 80px 0;
  text-align: center;
}

.cta-section h2 { color: var(--white); margin-bottom: 16px; }

.cta-section p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  margin-bottom: 32px;
}

.cta-section .btn {
  background: var(--white);
  color: var(--primary);
}

.cta-section .btn:hover {
  background: var(--gray-100);
  transform: translateY(-1px);
}

/* Team Grid */
.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 32px;
  max-width: 900px;
  margin: 0 auto;
}

.team-member {
  text-align: center;
}

.team-avatar {
  width: 120px;
  height: 120px;
  background: var(--gray-200);
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-weight: 700;
  color: var(--gray-600);
}

.team-member h4 { margin-bottom: 4px; }

.team-member p {
  color: var(--gray-600);
  font-size: 0.875rem;
}

/* Contact Form */
.contact-form {
  max-width: 600px;
  margin: 0 auto;
  background: var(--white);
  padding: 40px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--dark);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.2s;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--primary);
}

.form-group textarea { resize: vertical; min-height: 120px; }

.form-error {
  color: var(--accent);
  font-size: 0.875rem;
  margin-top: 6px;
  display: none;
}

.form-group.error input,
.form-group.error select,
.form-group.error textarea {
  border-color: var(--accent);
}

.form-group.error .form-error { display: block; }

.form-success {
  background: var(--success);
  color: var(--white);
  padding: 16px;
  border-radius: var(--radius-md);
  text-align: center;
  margin-bottom: 20px;
  display: none;
}

.form-success.show { display: block; }

/* Office Locations */
.locations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 32px;
  max-width: 900px;
  margin: 48px auto 0;
}

.location-card {
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  text-align: center;
}

.location-card h4 { margin-bottom: 8px; }

.location-card p { color: var(--gray-600); }

.location-card .highlight {
  color: var(--primary);
  font-weight: 600;
}

/* Footer */
.footer {
  background: var(--dark);
  padding: 60px 0 30px;
  color: var(--gray-400);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 48px;
  margin-bottom: 48px;
}

.footer-col h4 {
  color: var(--white);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  color: var(--gray-400);
  padding: 6px 0;
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  padding-top: 30px;
  border-top: 1px solid rgba(255,255,255,0.1);
  text-align: center;
  font-size: 0.875rem;
}

/* Feature Detail Sections */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
  margin-bottom: 60px;
}

.feature-detail:nth-child(even) { direction: rtl; }

.feature-detail:nth-child(even) > * { direction: ltr; }

.feature-detail-content h2 { margin-bottom: 20px; }

.feature-detail-content p { color: var(--gray-600); margin-bottom: 16px; }

.feature-detail-content ul {
  list-style: none;
}

.feature-detail-content li {
  padding: 8px 0;
  display: flex;
  align-items: center;
  gap: 12px;
}

.feature-detail-content li::before {
  content: '✓';
  color: var(--success);
  font-weight: 700;
}

.feature-visual {
  background: var(--gray-100);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--gray-400);
}

/* Integration Grid */
.integration-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 24px;
}

.integration-card {
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  text-align: center;
}

.integration-card h4 { margin-bottom: 8px; }

.integration-card p {
  color: var(--gray-600);
  font-size: 0.875rem;
}

/* Mission Section */
.mission-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.mission-content p {
  font-size: 1.25rem;
  color: var(--gray-700);
  line-height: 1.8;
}

/* Mobile Styles */
@media (min-width: 768px) {
  .nav-desktop { display: flex; }
  .mobile-nav-toggle { display: none; }

  .testimonial-card { flex: 0 0 calc(50% - 16px); margin: 0 8px; }
  .testimonials-track { gap: 16px; }

  .feature-detail { grid-template-columns: 1fr 1fr; }
  .feature-detail:nth-child(even) { direction: ltr; }
}

@media (max-width: 767px) {
  .hero { padding: 60px 0 40px; }
  .section { padding: 60px 0; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: 24px; }
  .pricing-card.featured { transform: none; }
  .feature-detail { grid-template-columns: 1fr; }
  .feature-detail:nth-child(even) { direction: ltr; }
  .contact-form { padding: 24px; }
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: fadeIn 0.5s ease forwards;
}

/* Counter Animation */
.stat-number[data-count] {
  opacity: 0;
  transition: opacity 0.3s;
}

.stat-number[data-count].visible {
  opacity: 1;
